import{_ as a,p as e,q as r,Y as h}from"./framework-e1bed10d.js";const i="/my-blog/assets/thread-bring-some-problem-82f41481.png",d={},n=h('<h1 id="多线程中的问题" tabindex="-1"><a class="header-anchor" href="#多线程中的问题" aria-hidden="true">#</a> 多线程中的问题</h1><h2 id="线程安全问题" tabindex="-1"><a class="header-anchor" href="#线程安全问题" aria-hidden="true">#</a> 线程安全问题</h2><h3 id="原子性" tabindex="-1"><a class="header-anchor" href="#原子性" aria-hidden="true">#</a> 原子性</h3><p>即一个操作或者多个操作，要么全部执行并且执行的过程不会被任何因素打断，要么就都不执行</p><p>原子操作：即不会被线程调度机制打断的操作，没有上下文切换</p><h3 id="可见性" tabindex="-1"><a class="header-anchor" href="#可见性" aria-hidden="true">#</a> 可见性</h3><p>当多个线程访问同一个变量时，一个线程修改了这个变量的值，其他线程能够立即看得到修改的值</p><h2 id="活跃性问题" tabindex="-1"><a class="header-anchor" href="#活跃性问题" aria-hidden="true">#</a> 活跃性问题</h2><p>为了解决可见性的问题，我们可以采取加锁的方式来解决，但如果加锁使用不当也容易引入其他问题</p><p>活跃性是指某件正确的事情最终会发生，但当某个操作无法继续下去的时候，就会发生活跃性问题</p><h3 id="死锁" tabindex="-1"><a class="header-anchor" href="#死锁" aria-hidden="true">#</a> 死锁</h3><p>死锁是指多个线程因为环形等待锁的关系而永远地阻塞下去</p><p><img src="'+i+'" alt="死锁"></p><h3 id="活锁" tabindex="-1"><a class="header-anchor" href="#活锁" aria-hidden="true">#</a> 活锁</h3><p>死锁是两个线程都在等待对方释放锁导致阻塞。而活锁的意思是线程没有阻塞，还活着呢。当多个线程都在运行并且都在修改各自的状态，而其他线程又依赖这个状态，就导致任何一个线程都无法继续执行，只能重复着自身的动作，于是就发生了活锁</p><h3 id="饥饿" tabindex="-1"><a class="header-anchor" href="#饥饿" aria-hidden="true">#</a> 饥饿</h3><p>如果一个线程无其他异常却迟迟不能继续运行，那基本上是处于饥饿状态了</p><p>常见的有几种场景:</p><ul><li>高优先级的线程一直在运行消耗 CPU，所有的低优先级线程一直处于等待；</li><li>一些线程被永久堵塞在一个等待进入同步块的状态，而其他线程总是能在它之前持续地对该同步块进行访问</li></ul><h2 id="性能问题" tabindex="-1"><a class="header-anchor" href="#性能问题" aria-hidden="true">#</a> 性能问题</h2><h3 id="创建线程开销" tabindex="-1"><a class="header-anchor" href="#创建线程开销" aria-hidden="true">#</a> 创建线程开销</h3><p>创建线程是直接向系统申请资源的，对操作系统来说，创建一个线程的代价是十分昂贵的，需要给它分配内存、列入调度等</p><h3 id="上下文切换" tabindex="-1"><a class="header-anchor" href="#上下文切换" aria-hidden="true">#</a> 上下文切换</h3><p>CPU 是很宝贵的资源，速度非常快，为了保证雨露均沾，通常会给不同的线程分配时间片，当 CPU 从执行一个线程切换到执行另一个线程时，CPU 需要保存当前线程的本地数据，程序指针等状态，并加载下一个要执行线程的本地数据，程序指针等，也就是『上下文切换』</p><p>一般减少上下文切换的方法有：</p><ul><li>无锁并发编程：可以参照 ConcurrentHashMap 锁分段的思想，不同的线程处理不同段的数据，这样在多线程竞争的条件下，可以减少上下文切换的时间。</li><li>CAS 算法，利用 Atomic + CAS 算法来更新数据，采用乐观锁的方式，可以有效减少一部分不必要的锁竞争带来的上下文切换。</li><li>使用最少线程：避免创建不必要的线程，如果任务很少，但创建了很多的线程，这样就会造成大量的线程都处于等待状态。</li><li>协程：在单线程里实现多任务的调度，并在单线程里维持多个任务间的切换</li></ul>',26),t=[n];function s(c,l){return e(),r("div",null,t)}const o=a(d,[["render",s],["__file","problem.html.vue"]]);export{o as default};
